/// <summary>File convenience methods for the unbounded binary column accessors of DocumentEntity (transfer blobs between the database and files in a single call; delegates to the Stream overloads).</summary>
public static class DocumentRepositoryBinaryStreamExtensions
{
    /// <summary>Reads the payload column into a file (delegates to the Stream overload; true = written, false = no row or NULL).</summary>
